FFStatus SequenceReset::toString(falconfix::FastBuffer &out, bool includeMilliseconds) const noexcept {
	static constexpr std::string_view HDR = "8=FIX4.2\x01""9=000000\x01""35=4\x01";
	static constexpr std::size_t HDR_BL_POS = 11;
	static constexpr std::size_t HDR_CALC_OFFSET = 18;

	out.clear();
	if (!out.reserve_noexcept(compute_buffer_size())) [[unlikely]] {
		return FF_SYS_ERR(BAD_ALLOC);
	}

	char *p = out.data();
	std::memcpy(p, HDR.data(), HDR.size());
	p += HDR.size();
	if ((p = m_Header.encode(p, includeMilliseconds)) == nullptr) {
		return FF_FIX_VALIDATION_ERR(COMPONENT_VALIDATION_FAILED, field_id::BeginString);
	}

	if (hasGapFillFlag()) { WRITE_TAG4(fix42::tag_const::GapFillFlag); *p++ = m_GapFillFlag ? 'Y' : 'N'; *p++ = fix42::serialize::SOH; }
	if (hasNewSeqNo()) { WRITE_TAG3(fix42::tag_const::NewSeqNo); p += falconfix::itoa(m_NewSeqNo, p); *p++ = fix42::serialize::SOH; }

	if ((p = m_Trailer.encode(p, includeMilliseconds)) == nullptr) {
		return FF_FIX_VALIDATION_ERR(COMPONENT_VALIDATION_FAILED, field_id::SignatureLength);
	}

	const std::size_t msg_len_no_checksum = static_cast<std::size_t>(p - out.data());
	const std::size_t body_len = msg_len_no_checksum - HDR_CALC_OFFSET;

	char *digits = out.data() + HDR_BL_POS;
	digits[0] = '0' + ((body_len / 100000) % 10);
	digits[1] = '0' + ((body_len / 10000 ) % 10);
	digits[2] = '0' + ((body_len / 1000  ) % 10);
	digits[3] = '0' + ((body_len / 100   ) % 10);
	digits[4] = '0' + ((body_len / 10    ) % 10);
	digits[5] = '0' +  (body_len           % 10);

	std::uint32_t cksum = 0;
	for (const char *it = out.data(); it != out.data() + msg_len_no_checksum; ++it) {
		cksum += static_cast<unsigned char>(*it);
	}
	cksum &= 0xFF;

	*p++ = '1'; *p++ = '0'; *p++ = '=';
	*p++ = char('0' + (cksum / 100));
	*p++ = char('0' + ((cksum / 10) % 10));
	*p++ = char('0' + (cksum % 10));
	*p++ = fix42::serialize::SOH;
	out.commit(static_cast<std::size_t>(p - out.data()));
	return FF_OK();
}

bool SequenceReset::setField(int32_t tag, const char *begin, const char *end) noexcept {
	const std::size_t len = static_cast<std::size_t>(end - begin);

	switch (tag) {
	case field_id::GapFillFlag: setGapFillFlag(fix42::parser::parse_bool(begin, end)); return true;
	case field_id::NewSeqNo: setNewSeqNo(falconfix::atoi(begin, end)); return true;
	default: return false;
	}
}

